// Author:@南哥AGI研习社 (B站 or YouTube 搜索“南哥AGI研习社”)

// 获取所有输入项
const items = $input.all();
// 提取第一项中的数据列表
const list = items[0].json.data.items;

// 遍历列表，为每个选题计算综合排名得分
const processedList = list.map(row => {
  // 获取发布时间的毫秒时间戳
  const pubMillis = row.fields["发布时间"]; // 毫秒时间戳

  // ===== 计算新鲜度（小时，保留两位小数）=====
  const freshnessHours =
    ($now.toMillis() - pubMillis) / (1000 * 60 * 60);
  const freshnessHoursRounded = Number(freshnessHours.toFixed(1));

  // ===== 1. 执行槽位权重 =====
  const slot = row.fields["执行槽位"]; // "必做主线" / "高优先" / "中优先" / "观察"
  let slotWeight = 0;
  if (slot === "必做主线") slotWeight = 20;
  else if (slot === "高优先") slotWeight = 15;
  else if (slot === "中优先") slotWeight = 8;
  else slotWeight = 0;

  // ===== 2. 新鲜度加分 =====
  let freshnessBonus = 0;
  if (freshnessHoursRounded <= 6) {
    freshnessBonus = 10;
  } else if (freshnessHoursRounded <= 24) {
    freshnessBonus = 5;
  } else {
    freshnessBonus = 0;
  }

  // ===== 3. 紧急预警加分 =====
  const urgentFlag = row.fields["紧急预警标记"];
  const urgentBool = urgentFlag === true;
  const urgentBonus = urgentBool ? 15 : 0;

  // ===== 4. 影响力加权 =====
  const influenceScore = Number(row.fields["影响力重要性得分"] || 0);
  const influenceWeighted = influenceScore * 0.5;

  // ===== 5. 人工优先级加分 =====
  const manualAdjust = row.fields["人工优先级修正"]; // "手动提升" / "手动降低" / "不改"
  let manualBonus = 0;
  if (manualAdjust === "手动提升") manualBonus = 25;
  else if (manualAdjust === "手动降低") manualBonus = -25;
  else manualBonus = 0;

  // ===== 6. 计算最终排名得分 =====
  const baseScore = Number(row.fields["最终热度得分"] || 0);
  const rankScore =
    baseScore +
    slotWeight +
    freshnessBonus +
    urgentBonus +
    influenceWeighted +
    manualBonus;

  // ===== 7. 生成原因片段 =====
  const reasonSnippets = [];

  // 最终热度得分 / 综合分
  if (baseScore >= 85) {
    reasonSnippets.push("综合分极高");
  } else if (baseScore >= 75) {
    reasonSnippets.push(`综合分${baseScore}(必做级)`);
  } else if (baseScore >= 60) {
    reasonSnippets.push(`综合分${baseScore}(高)`);
  }

  // 影响力重要性得分
  if (influenceScore >= 20) {
    reasonSnippets.push("影响力极高");
  } else if (influenceScore >= 18) {
    reasonSnippets.push(`影响力${influenceScore}(高)`);
  }

  // 领域相关度得分
  const relevanceScore = Number(row.fields["领域相关度得分"] || 0);
  if (relevanceScore === 25) {
    reasonSnippets.push("相关度满分");
  } else if (relevanceScore >= 20) {
    reasonSnippets.push("相关度高");
  }

  // 新鲜度（小时）
  if (freshnessHoursRounded <= 6) {
    reasonSnippets.push(`超新鲜(${freshnessHoursRounded.toFixed(1)}h)`);
  } else if (freshnessHoursRounded <= 24) {
    reasonSnippets.push(`新鲜(${freshnessHoursRounded.toFixed(1)}h)`);
  }

  // 紧急预警
  if (urgentBool) {
    reasonSnippets.push("紧急预警");
  }

  // 人工优先级修正
  if (manualAdjust === "手动提升") {
    reasonSnippets.push("人工提升");
  }

  // 返回处理后的选题对象
  return {
    记录ID: row.record_id,
    选题ID: row.fields["选题ID"],
    标题: row.fields["标题"][0].text,
    摘要: row.fields["摘要"][0].text,
    最终热度得分: baseScore,
    领域相关度得分: relevanceScore,
    时效性热点程度得分: row.fields["时效性热点程度得分"],
    深度新颖性得分: row.fields["深度新颖性得分"],
    影响力重要性得分: influenceScore,
    一级赛道: row.fields["一级赛道"],
    内容类型: row.fields["内容类型"],
    执行槽位: slot,
    竞争度: row.fields["竞争度"],
    变现潜力: row.fields["变现潜力"],
    紧急预警标记: urgentFlag,
    发布时间: DateTime.fromMillis(pubMillis).toFormat('yyyy/MM/dd HH:mm:ss'),
    新鲜度: freshnessHoursRounded,
    来源名称: row.fields["来源名称"][0].text,
    来源类型: row.fields["来源类型"],
    原始链接: row.fields["原始链接"].link,
    人工优先级修正: manualAdjust,
    排序综合得分: rankScore,
    原因片段: reasonSnippets
  };
});

// 返回包含所有处理结果的数组
return [
  {
    json: {
      allResults: processedList,
    },
  },
];

