// 转义函数
function escapeForFeishu(obj) {
    // 先转为标准JSON字符串(压缩格式)
    let jsonStr = JSON.stringify(obj);

    // 再次stringify并去掉最外层引号,实现转义
    let escapedStr = JSON.stringify(jsonStr);
    escapedStr = escapedStr.slice(1, -1);

    return escapedStr;
}

// 对内容进行转义
const escapedContent = escapeForFeishu(postZhCn);

// 构建最终输出
