// Author:@南哥AGI研习社 (B站 or YouTube 搜索"南哥AGI研习社")

// 获取n8n工作流中传入的所有输入数据
const inputData = $input.all();
// 提取第一个输入项的JSON数据
const data = inputData[0].json;

// ============================================
// 数据提取部分
// ============================================

// 从输入数据中提取output对象
const output = data.output;
// 提取必做主线选题数组，如果不存在则使用空数组
const topHead = output.topHead || [];
// 提取快讯池选题数组，如果不存在则使用空数组
const topQuick = output.topQuick || [];
// 提取深度池选题数组，如果不存在则使用空数组
const topDeep = output.topDeep || [];
// 提取统计数据对象，如果不存在则使用空对象
const stats = output.stats || {};
// 提取智能建议数组，如果不存在则使用空数组
const recommendations = output.recommendations || [];

// ============================================
// 初始化富文本内容数组
// 每个元素都是一个段落，段落内可包含多个文本块
// ============================================
const content = [];

// ============================================
// 报告标题区域
// ============================================

// 添加报告主标题（加粗样式，包含日期和时间）
const formattedDateTime = $now.toFormat('yyyy/MM/dd HH:mm:ss');
content.push([
  { tag: "text", text: `📊 AI智能决策每日清单(${formattedDateTime})\n`, style: ["bold"] }
]);

// 添加装饰性分隔线
content.push([
  { tag: "text", text: "━━━━━━━━━━━━━━━━━━━━\n" }
]);

// ============================================
// 数据概览部分
// ============================================

// 添加数据概览标题（加粗样式）
content.push([
  { tag: "text", text: "📈 数据概览\n", style: ["bold"] }
]);
// 添加第一行统计数据：总数、已处理数、紧急数量
content.push([
  { tag: "text", text: `总计: ${stats.total} | 已处理: ${stats.processed} | 紧急: ${stats.urgent_count}\n` }
]);
// 添加第二行统计数据：主线数、快讯数、深度数，末尾加两个换行符增加间距
content.push([
  { tag: "text", text: `主线: ${stats.head_count} | 快讯: ${stats.quick_count} | 深度: ${stats.deep_count}\n\n` }
]);

// ============================================
// 必做主线（紧急）部分
// ============================================

// 判断是否有必做主线选题
if (topHead.length > 0) {
  // 添加必做主线板块标题（加粗样式）
  content.push([
    { tag: "text", text: "🚨 必做主线（紧急）\n", style: ["bold"] }
  ]);
  // 添加装饰性分隔线
  content.push([
    { tag: "text", text: "━━━━━━━━━━━━━━━━━━━━\n" }
  ]);

  // 遍历每个必做主线选题
  topHead.forEach((item, index) => {
    // 添加选题标题（序号 + 标题，加粗样式）
    content.push([
      { tag: "text", text: `${index + 1}. ${item.title}\n`, style: ["bold"] }
    ]);

    // 添加摘要
    if (item.summary) {
      content.push([
        { tag: "text", text: `   📄 摘要: ${item.summary}\n` }
      ]);
    }

    // 添加原始链接
    if (item.source_link) {
      content.push([
        { tag: "text", text: "   🔗 原文链接: " },
        { tag: "a", text: "点击查看", href: item.source_link },
        { tag: "text", text: "\n" }
      ]);
    }

    // 添加评分信息：综合评分和排名分
    content.push([
      { tag: "text", text: `   📌 综合评分: ${item.final_score} | 排名分: ${item.rank_score}\n` }
    ]);
    // 添加赛道和执行槽信息
    content.push([
      { tag: "text", text: `   🎯 赛道: ${item.primary_track} | 执行槽: ${item.execution_slot}\n` }
    ]);
    // 添加新鲜度、竞争程度、变现潜力信息
    content.push([
      { tag: "text", text: `   ⏰ 新鲜度: ${item.freshness_hours}小时 | 竞争: ${item.competition_level} | 变现: ${item.monetization_potential}\n` }
    ]);

    // 如果存在紧急警告，则添加分配原因（加粗样式强调）
    if (item.urgent_alert) {
      content.push([
        { tag: "text", text: `   ⚠️ ${item.allocation_reason}\n`, style: ["bold"] }
      ]);
    }

    // 添加执行策略建议
    content.push([
      { tag: "text", text: `   💡 策略: ${item.execution_strategy}\n` }
    ]);

    // 如果存在变现路径，则添加变现路径信息
    if (item.monetization_path) {
      content.push([
        { tag: "text", text: `   💰 变现路径: ${item.monetization_path}\n` }
      ]);
    }

    // 如果存在SEO关键词且不为空数组，则添加关键词列表
    if (item.seo_keywords && item.seo_keywords.length > 0) {
      content.push([
        { tag: "text", text: `   🔍 SEO关键词: ${item.seo_keywords.join(', ')}\n` }
      ]);
    }

    // 添加竞争策略，末尾加两个换行符作为选题间隔
    content.push([
      { tag: "text", text: `   ⚔️ 竞争策略: ${item.competition_strategy}\n\n` }
    ]);
  });
}

// ============================================
// 快讯池选题部分
// ============================================

// 判断是否有快讯池选题
if (topQuick.length > 0) {
  // 添加快讯池板块标题（加粗样式）
  content.push([
    { tag: "text", text: "⚡ 快讯池选题\n", style: ["bold"] }
