    ]);
  });
}

// ============================================
// 深度池选题部分
// ============================================

// 判断是否有深度池选题
if (topDeep.length > 0) {
  // 添加深度池板块标题（加粗样式）
  content.push([
    { tag: "text", text: "📖 深度池选题\n", style: ["bold"] }
  ]);
  // 添加装饰性分隔线
