    { tag: "text", text: "━━━━━━━━━━━━━━━━━━━━\n" }
  ]);

  // 遍历每个深度池选题
  topDeep.forEach((item, index) => {
    // 添加选题标题（序号 + 标题，加粗样式）
    content.push([
      { tag: "text", text: `${index + 1}. ${item.title}\n`, style: ["bold"] }
    ]);

    // 添加摘要
    if (item.summary) {
      content.push([
        { tag: "text", text: `   📄 摘要: ${item.summary}\n` }
      ]);
    }

    // 添加原始链接
    if (item.source_link) {
      content.push([
        { tag: "text", text: "   🔗 原文链接: " },
        { tag: "a", text: "点击查看", href: item.source_link },
        { tag: "text", text: "\n" }
      ]);
    }

    // 添加评分信息
    content.push([
      { tag: "text", text: `   📌 综合评分: ${item.final_score} | 排名分: ${item.rank_score}\n` }
    ]);
    // 添加赛道信息
    content.push([
      { tag: "text", text: `   🎯 赛道: ${item.primary_track}\n` }
    ]);
    // 添加分配原因
    content.push([
      { tag: "text", text: `   📝 ${item.allocation_reason}\n` }
    ]);
    // 添加执行策略
    content.push([
      { tag: "text", text: `   💡 策略: ${item.execution_strategy}\n` }
    ]);

    // 如果存在变现路径，添加变现路径并加两个换行符；否则只加一个换行符
    if (item.monetization_path) {
      content.push([
        { tag: "text", text: `   💰 变现路径: ${item.monetization_path}\n\n` }
      ]);
    } else {
      content.push([
        { tag: "text", text: "\n" }
      ]);
    }
  });
}

// ============================================
// 赛道分布统计部分
// ============================================

// 判断是否存在赛道分布数据
if (stats.track_distribution) {
  // 添加赛道分布板块标题（加粗样式）
  content.push([
    { tag: "text", text: "🎨 赛道分布\n", style: ["bold"] }
  ]);
  // 添加装饰性分隔线
