    { tag: "text", text: "━━━━━━━━━━━━━━━━━━━━\n" }
  ]);

  // 遍历赛道分布对象的每个键值对
  for (const [track, count] of Object.entries(stats.track_distribution)) {
    // 只显示数量大于0的赛道
    if (count > 0) {
      content.push([
        { tag: "text", text: `   ${track}: ${count}篇\n` }
      ]);
    }
  }
  // 赛道分布后添加一个空行
  content.push([{ tag: "text", text: "\n" }]);
}

// ============================================
// 智能建议部分
// ============================================

// 判断是否有智能建议
if (recommendations.length > 0) {
  // 添加智能建议板块标题(加粗样式)
  content.push([
    { tag: "text", text: "💡 智能建议\n", style: ["bold"] }
  ]);
  // 添加装饰性分隔线
  content.push([
    { tag: "text", text: "━━━━━━━━━━━━━━━━━━━━\n" }
  ]);

  // 遍历每条智能建议
  recommendations.forEach((rec, index) => {
    // 添加建议内容
    content.push([
      { tag: "text", text: `${rec}\n` }
    ]);
  });
}

// ============================================
// 添加系统链接
// ============================================

// 添加装饰性分隔线
content.push([
  { tag: "text", text: "\n━━━━━━━━━━━━━━━━━━━━\n" }
]);

// 添加系统链接
content.push([
  { tag: "text", text: "🔗 " },
  { tag: "a", text: "点击进入系统查看详情", href: "https://mcn33lfbwjgi.feishu.cn/base/VrjBb09mZaZauLsFdRrcqTSsnVe?table=tbl75OvZpQtdLABJ&view=vewKCwXwPg" },
  { tag: "text", text: "\n" }
]);

// ============================================
// 构建飞书消息对象
// ============================================

// 构建符合飞书API规范的富文本消息对象
const feishuMessage = {
  // 消息类型:富文本
  msg_type: "post",
  // 消息内容
  content: {
    // 富文本内容
    post: {
      // 简体中文版本
      zh_cn: {
        // 消息标题
        title: "🤖 智能化选题评审与决策支持平台",
        // 消息正文内容(之前构建的content数组)
        content: content
      }
    }
  }
};

// ============================================
// 返回结果
// ============================================

// 将构建好的飞书消息对象作为JSON返回给n8n工作流的下一个节点
return { json: feishuMessage };

