// Author:@南哥AGI研习社 (B站 or YouTube 搜索"南哥AGI研习社")

// 获取上一个节点的输出数据
const inputData = $input.all()[0].json.output;

// 定义原始键名与中文名称的映射关系
const mapping = {
  'topHead': '头版池',
  'topQuick': '快讯池',
  'topDeep': '深度池'
};

let results = [];

// 遍历映射关系
for (const [key, chineseName] of Object.entries(mapping)) {
  const records = inputData[key];

  // 如果该分类下有数据且是数组，则提取 record_id
  if (records && Array.isArray(records)) {
    records.forEach(record => {
      results.push({
        json: {
          record_id: record.record_id,
          record_flag: chineseName // 使用对应的中文名称
        }
      });
    });
  }
}

// 返回符合 n8n 标准结构的数组
return results;
